changeSet.sql:
CREATE OR ALTER FUNCTION [dbo].[GenerateAssetTypeUrl] ( @AssetTypeID int ) RETURNS varchar(500) AS BEGIN DECLARE @Type varchar(50), @TypeID int; DECLARE @Url varchar(500) = '';
select @Type = T.[Object], @TypeID = T.ObjectID from AssetType T where T.ID = @AssetTypeID;
SET @Url = CASE @Type WHEN 'ArtifactType' THEN 'artifact/' + CAST(@TypeID as varchar) WHEN 'ReferenceItemType' THEN 'reference/' + CAST(@TypeID as varchar) WHEN 'PolicyType' THEN 'policy/' + CAST(@TypeID as varchar) + '/structure' WHEN 'ResourceType' THEN 'resource/list/' + CAST(@TypeID as varchar) WHEN 'RuleType' THEN 'quality/rule/' + CAST(@TypeID as varchar) WHEN 'TaxonomyType' THEN 'model/' + CAST(@TypeID as varchar) + '/structure' END
RETURN @Url END
